from pathlib import Path
from PIL import Image
import json,html
R=Path(__file__).resolve().parents[1];D=R/'docs/performance/visual-loading';P=R/'target/temple-run/web/public/visual-audit';(P/'images').mkdir(parents=True,exist_ok=True)
for name in ['before','after','after-ktx','30s','half-road','wood','cliff']:
 im=Image.open(R/f'docs/screenshots/visual-loading/visual-{name}.png');im.save(P/f'images/{name}.webp',quality=85,method=6)
s=json.loads((D/'summary.json').read_text());rows=[]
for name,row in s.items():
 if 'median' not in row:continue
 m=row['median'];rows.append(f'<tr><th>{html.escape(name)}</th><td>{m["button"]/1000:.2f}s</td><td>{m["tti"]/1000:.2f}s</td><td>{m["bytes"]/1000:.1f}KB</td><td>{m["network"]:.0f}</td></tr>')
fig=lambda name,label:f'<figure><a href="images/{name}.webp" target="_blank"><img loading="lazy" src="images/{name}.webp" width="375" height="812" alt="{label}"></a><figcaption>{label}</figcaption></figure>'
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>视觉恢复与加载证据 · Temple Run</title><style>
*{box-sizing:border-box}body{margin:0;background:#152d2a;color:#e8e2cc;font:16px/1.7 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:32px 22px}h1{font:700 clamp(30px,5vw,56px)/1.12 Georgia,serif;color:#e7c07b}h2{margin-top:60px;color:#e7c07b}p{max-width:850px}a{color:#f0cc87}nav{display:flex;gap:24px;flex-wrap:wrap;border-block:1px solid #688077;padding:12px 0}.pair,.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}figure{margin:0;background:#203c35;padding:12px}img{width:100%;height:auto;display:block}figcaption{padding:12px 0;color:#eed9b0}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{padding:12px 8px;border-bottom:1px solid #536a5e;text-align:left}.table{overflow:auto}.note{border-left:3px solid #c79d59;padding:12px 20px;background:#203c35}code{font-size:14px}footer{padding:50px 0;color:#a1b9a8}
</style><main><p>TEMPLE RUN / ENGINEERING EVIDENCE</p><h1>完整视觉，<br>可核对的加载成本。</h1><p>修复了“更快，但场景没了”。道路、墙、立柱、树与障碍恢复真实几何和贴图；KTX2在当前局更新材质，Cache Storage保留哈希素材。</p><nav><a href="#compare">同机位对照</a><a href="#runtime">运行中验证</a><a href="#perf">冷／温／热</a><a href="#rules">格式与缓存规则</a><a href="../design-evidence/">游戏架构证据</a></nav>
<h2 id="compare">同机位：距离20，相同相机</h2><div class="pair">'''+fig('before','修复前：只剩承重顶面，墙与入口缺失')+fig('after','修复后：真实路面、桥墙、立柱与入口；无1×1替代')+'''</div><p>点击图片放大。对照采于提交前工作区，因此截图版本标签仍为基线7c2e7aa；不是声称旧版线上已经有新画面。两图采用同一测试路段、距离与相机。</p>
<h2 id="runtime">当前局热更新与完整路面</h2><div class="gallery">'''+fig('after-ktx','KTX2到位后，当前局14处材质引用更新，真猴子仍在')+fig('30s','31.8秒模拟跑动：测试加速保护，非自然无道具存活记录')+fig('half-road','半边路：真实贴图，右侧支撑；缺失侧会掉落')+fig('wood','受控木桥段：原模型、木纹、柱与绳索')+fig('cliff','受控悬崖段：已移除遮挡纹理的灰色支撑面')+'''</div>
<h2 id="perf">性能：每态三轮中位数</h2><p class="note">375×812、Slow4G（180000B/s、562.5ms）+6×CPU。完整视觉冷启动仍未达到3秒；不以省略主要素材换取达标。local为生产gzip6服务；public为Pages实测（若已有数据）。</p><div class="table"><table><tr><th>组别</th><th>按钮可用</th><th>可玩</th><th>首屏传输</th><th>网络请求</th></tr>'''+''.join(rows)+'''</table></div><p>冷：清持久缓存且禁HTTP缓存。温：持久缓存命中、HTTP缓存禁用。热：二者命中，先明确预热。可玩指开始动作进入playing并完成两个模拟步，不计教程／开场观看；非真机结论，不是Lighthouse TTI。</p>
<h2 id="rules">格式与缓存规则</h2><p>开局包含69份现有道路／障碍几何与UV1；壁面/树512px，光照256px，其他必要贴图128px。所有源图保留。细节仍有降分辨率与有损压缩损失，不声称像素一致。</p><p>壁面/树/水使用ETC1S，叶片和烘焙光使用UASTC，含mipmap。颜色按sRGB编码，原Gamma材质采样保持NoColorSpace。Basis/纹理失败回退真实WebP。KTX2不占首帧关键路径；GPU时间查询不可用时不伪造数值。</p><p>Cache Storage按内容哈希缓存开局包、模型、rig、纹理与转码器；新构建清旧命名空间。32MiB上限、FIFO淘汰；配额、隐私限制、读取超时回退网络。<code>?texture=webp</code>与<code>?cache=off</code>可作对照。</p><p>诊断：<code>window.__startupTiming</code>、<code>__assetCache</code>、<code>__visualTextures</code>、<code>__visualUpgrade</code>。只热替换材质，不在玩家脚下更换道路几何。</p><footer>截图、原始测量与规则来源均保存在仓库docs/performance/visual-loading。三态与GPU估算有明确边界，未将模拟器成绩当成手机实测。</footer></main></html>'''
(P/'index.html').write_text(page);print('Visual audit:',sum(f.stat().st_size for f in P.rglob('*')if f.is_file()),'bytes')
